  const errors=[],stage=lead.stage;if(stage==="New Lead"&&nextStage==="Scoping & KYC"&&!lead.companyName||stage==="New Lead"&&nextStage==="Scoping & KYC"&&!lead.primarySector||stage==="New Lead"&&nextStage==="Scoping & KYC"&&!lead.branchLocation||stage==="New Lead"&&nextStage==="Scoping & KYC"&&!lead.initialService)errors.push("Capture company name, sector, branch and an initial service before scoping.");
