  if(stage==="EL Signed"&&nextStage==="Active Engagement"){if(!lead.el?.signedReference)errors.push("Attach or record the signed Engagement Letter PDF reference before activation.");if(!kycDocumentsVerified(lead))errors.push("A Manager must verify the Certificate of Incorporation, KRA PIN and CR12 before activation.");if(!lead.kyc?.conflictCleared)errors.push("The conflict-of-interest check must remain cleared before activation.");if(lead.initialService==="Statutory Audit"&&!lead.icpakRefNo)errors.push("Record the ICPAK Reference No. before activating a Statutory Audit.")}
  if(stage==="Active Engagement"&&nextStage==="WIP / Billing"){if(!lead.resources?.supervisorUserId||!lead.resources?.assistantUserId||!lead.resources?.plannedWeekStart||!(Number(lead.resources?.assistantPlannedHours)>0))errors.push("Assign a Supervisor and Assistant staff ID, planned week and planned assistant hours before WIP setup.");const taxFrequency=lead.invoiceSchedule?.taxBillingFrequency;if(isTaxEngagement(lead)&&taxFrequency&&taxFrequency!=="One-off"){if(!(Number(lead.invoiceSchedule?.taxBillingFee)>0)||!lead.invoiceSchedule?.firstTaxInvoiceDate||!(Number(lead.invoiceSchedule?.paymentTermsDays)>0))errors.push("For a recurring tax project, record billing frequency, fee per period, first invoice date and payment terms before WIP setup.")}else{const invoiceTotal=(Number(lead.invoiceSchedule?.firstPercent)||0)+(Number(lead.invoiceSchedule?.secondPercent)||0);if(!lead.invoiceSchedule?.firstMilestone||!lead.invoiceSchedule?.secondMilestone||invoiceTotal!==100)errors.push("Set both invoice milestones and make their percentages total 100% before WIP setup.")}const capacity=capacitySummary(lead,records);if(capacity.over&&!lead.resources?.capacityOverrideReason)errors.push(`Assistant capacity is ${capacity.hours} hours for the planned week. Reallocate work or record an authorised capacity override reason.`)}
