function renderLifecycleKanban(){const board=document.getElementById("lifecycleKanban");board.innerHTML=CRM.lifecycleStages.map(stage=>{const records=lifecycleRecords.filter(record=>record.stage===stage),next=nextLifecycleStage(stage),hints={"New Lead":"Capture and route the enquiry.","Scoping & KYC":"Record scope, KYC documents and conflict check.","Proposal Sent":"Price the work and obtain approval where required.","EL Signed":"Record signed EL; activation remains blocked until KYC is verified.","Active Engagement":"Service workflow is active; assign delivery resources.","WIP / Billing":"Track WIP against the agreed fee and invoice schedule.","Closed / Archived":"Retained for history and reporting."},cards=records.map(lead=>`<article class="lifecycle-card"><h4>${escapeHtml(lead.companyName)}</h4><p>${escapeHtml(lead.primarySector)} · ${escapeHtml(lead.branchLocation)}</p><p class="inline-metric">${lead.proposal?.hours?`${lead.proposal.hours}h · ${formatKes(calculateProposal(lead.proposal).total)}`:"Fee not set"}</p><div>${lifecyclePills(lead)}</div><div class="client-actions"><button type="button" data-lifecycle-action="edit" data-id="${lead.id}">Edit</button>${next?`<button type="button" data-lifecycle-action="advance" data-id="${lead.id}">Advance to ${escapeHtml(next)}</button>`:""}${lead.workflowTasks?.length?`<button type="button" data-lifecycle-action="tasks" data-id="${lead.id}">Tasks</button>`:""}</div></article>`).join("")||'<p class="stage-note">No records</p>';return `<section class="kanban-column"><h3>${escapeHtml(stage)} <span class="kanban-count">${records.length}</span></h3><p class="stage-note">${escapeHtml(hints[stage])}</p>${cards}</section>`}).join("")}
