function initialiseLifecycle(){const form=document.getElementById("lifecycle-form");["leadPrimarySector","leadService","proposalHours","hourlyRate","vatRate","partnerApprovalThreshold","bundleService","bundleDiscount","assistantUserId","plannedWeekStart","assistantPlannedHours"].forEach(id=>document.getElementById(id).addEventListener("input",refreshLifecycleCalculatedFields));form.addEventListener("submit",event=>{event.preventDefault();if(!form.reportValidity())return;const existing=lifecycleRecordById(document.getElementById("lifecycleId").value),record=buildLifecycleRecord(form,existing),index=lifecycleRecords.findIndex(item=>item.id===record.id);if(index>=0)lifecycleRecords[index]=record;else{lifecycleRecords.push(record);logCommunication({subject:"New Lead Created",communicationType:"Internal Note",direction:"Internal",body:`Lead created from the lifecycle intake. Initial service interest: ${record.initialService||"Not recorded"}.`,staffId:"Practice Administration",status:"No Action Required",leadId:record.id,serviceOffered:record.initialService,branchLocation:record.branchLocation})}saveLifecycleRecords();saveOperations();renderLifecycleKanban();renderCommunicationHub();showLifecycleNotice(`${record.companyName} saved in ${record.stage}. Use the Kanban action after saving the evidence for its next gate.`)});document.getElementById("newLifecycleLead").addEventListener("click",resetLifecycleForm);document.getElementById("lifecycleKanban").addEventListener("click",event=>{const button=event.target.closest("button[data-lifecycle-action]");if(!button)return;const lead=lifecycleRecordById(button.dataset.id);if(!lead)return;if(button.dataset.lifecycleAction==="edit"){fillLifecycleForm(lead);return}if(button.dataset.lifecycleAction==="tasks"){displayLifecycleTasks(lead);return}if(button.dataset.lifecycleAction==="advance"){const next=nextLifecycleStage(lead.stage),errors=validateStageTransition(lead,next);if(errors.length){showLifecycleNotice(`Cannot advance ${lead.companyName}: ${errors.join(" ")}`,true);return}lead.stage=next;if(next==="Active Engagement"){lead.activatedAt=new Date().toISOString();lead.workflowTasks=generateEngagementWorkflow(lead);logCommunication({subject:`Engagement Confirmed: ${lead.companyName}`,communicationType:"Email",direction:"Outbound",body:"Signed Engagement Letter accepted and project workflow activated.",staffId:"Practice Administration",status:"No Action Required",leadId:lead.id,engagementId:lead.id,serviceOffered:lead.initialService,branchLocation:lead.branchLocation})}if(next==="WIP / Billing")lead.wipCreated=true;lead.updatedAt=new Date().toISOString();saveLifecycleRecords();saveOperations();renderLifecycleKanban();renderCommunicationHub();showLifecycleNotice(`${lead.companyName} advanced to ${next}.${next==="Active Engagement"?` ${lead.workflowTasks.length} delivery task${lead.workflowTasks.length===1?"":"s"} created.`:""}`)}});refreshLifecycleCalculatedFields();renderLifecycleKanban()}

