function showHrNotice(message,error=false){const notice=document.getElementById("hrNotice");notice.textContent=message;notice.classList.add("show");notice.style.background=error?"#fbe8e8":"";notice.style.borderColor=error?"#d8aaaa":"";notice.style.color=error?"#8b2828":"";clearTimeout(showHrNotice.timer);showHrNotice.timer=setTimeout(()=>notice.classList.remove("show"),8000)}
function rangesOverlap(startA,endA,startB,endB){return startA<=endB&&endA>=startB}
function leaveIsBusySeason(startDate,endDate){const startYear=Number(startDate.slice(0,4)),endYear=Number(endDate.slice(0,4));for(let year=startYear;year<=endYear;year+=1){if(rangesOverlap(startDate,endDate,`${year}-01-15`,`${year}-04-30`))return true}return false}
function approvedLeaveOverlap(staffId,startDate,endDate){return leaveRequests.find(request=>request.staffId===staffId&&request.status==="Approved"&&rangesOverlap(startDate,endDate,request.startDate,request.endDate))}
function assignmentOverlap(staffId,startDate,endDate){return staffAssignments.find(assignment=>assignment.staffId===staffId&&rangesOverlap(startDate,endDate,assignment.plannedStartDate,assignment.plannedEndDate))}
function dayCount(startDate,endDate){return Math.floor((new Date(`${endDate}T00:00:00Z`)-new Date(`${startDate}T00:00:00Z`))/86400000)+1}
