function updateHrRiskNotices(){const start=document.getElementById("leaveStartDate").value,end=document.getElementById("leaveEndDate").value,leaveNotice=document.getElementById("leaveRiskNotice"),staffId=document.getElementById("assignmentStaffId").value.trim(),assignmentStart=document.getElementById("assignmentStart").value,assignmentEnd=document.getElementById("assignmentEnd").value,assignmentNotice=document.getElementById("assignmentRiskNotice");leaveNotice.textContent=start&&end?(leaveIsBusySeason(start,end)?"Busy-season leave: this request must route to the Engagement Partner. The approval will be blocked while active fieldwork is assigned.":"Standard leave: Manager approval is sufficient unless a staffing conflict is identified."):"Enter leave dates to assess busy-season approval and active-fieldwork impact.";assignmentNotice.textContent=staffId&&assignmentStart&&assignmentEnd?(assignmentOverlap(staffId,assignmentStart,assignmentEnd)||approvedLeaveOverlap(staffId,assignmentStart,assignmentEnd)?"Conflict detected: this person is already assigned or on approved leave during part of the selected range. Allocation will be blocked.":"No current assignment or approved-leave conflict detected for this staff ID."):"The system blocks a person who has an overlapping engagement assignment or approved leave."}
