const attendanceNetworkPrefixes=[];
function showAttendanceNotice(message,error=false){const notice=document.getElementById("attendanceNotice");notice.textContent=message;notice.classList.add("show");notice.style.background=error?"#fbe8e8":"";notice.style.borderColor=error?"#d8aaaa":"";notice.style.color=error?"#8b2828":"";clearTimeout(showAttendanceNotice.timer);showAttendanceNotice.timer=setTimeout(()=>notice.classList.remove("show"),8000)}
function attendanceWeekStart(date){const value=new Date(`${date}T00:00:00Z`),day=value.getUTCDay()||7;value.setUTCDate(value.getUTCDate()-day+1);return value.toISOString().slice(0,10)}
function attendanceHours(clockIn,clockOut){if(!clockIn||!clockOut)return 0;return Math.max(0,(new Date(clockOut).getTime()-new Date(clockIn).getTime())/3600000)}
function timeOfDay(value){return value?value.slice(11,16):""}
function minutesAfter(value,reference){const [hours,minutes]=value.split(":").map(Number),[refHours,refMinutes]=reference.split(":").map(Number);return hours*60+minutes-(refHours*60+refMinutes)}
function attendanceBusySeason(date){const month=Number(date.slice(5,7));return month>=1&&month<=4}
function approvedLeaveFor(staffId,date){return leaveRequests.find(request=>request.staffId===staffId&&request.status==="Approved"&&date>=request.startDate&&date<=request.endDate)}
function approvedAttendanceNetwork(ipAddress){return Boolean(ipAddress)&&attendanceNetworkPrefixes.some(prefix=>ipAddress.startsWith(prefix))}
function exceptionFor(attendanceId,type){return attendanceExceptions.find(item=>item.attendanceId===attendanceId&&item.exceptionType===type)}
function addAttendanceException(attendance,exceptionType,minutesVariance,reason=""){if(exceptionFor(attendance.id,exceptionType))return;attendanceExceptions.push({id:crypto.randomUUID(),attendanceId:attendance.id,staffId:attendance.staffId,date:attendance.date,exceptionType,minutesVariance,reason,status:"Pending",createdAt:new Date().toISOString()})}
function syncApprovedLeaveAttendance(request,approver=""){for(let offset=0;offset<request.totalDays;offset+=1){const date=addDays(request.startDate,offset),existing=attendanceLogs.find(log=>log.staffId===request.staffId&&log.date===date),record={id:existing?.id||crypto.randomUUID(),staffId:request.staffId,position:existing?.position||"",date,clockInTime:null,clockOutTime:null,workLocation:"ON_LEAVE",ipAddress:"",status:"On Leave",totalHoursWorked:0,approvedBy:approver||request.approvedBy||null,requiresManagerReview:false,leaveRequestId:request.id,createdAt:existing?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(existing){const index=attendanceLogs.findIndex(log=>log.id===existing.id);attendanceLogs[index]=record}else attendanceLogs.push(record)}}
function syncAllApprovedLeaveAttendance(){leaveRequests.filter(request=>request.status==="Approved").forEach(request=>syncApprovedLeaveAttendance(request,request.approvedBy||""))}
function attendanceGaps(){const groups={};attendanceLogs.filter(log=>log.clockOutTime&&["Present","Late","Half Day"].includes(log.status)).forEach(log=>{const key=`${log.staffId}|${attendanceWeekStart(log.date)}`;if(!groups[key])groups[key]={staffId:log.staffId,weekStart:attendanceWeekStart(log.date),attendanceHours:0,timesheetHours:0};groups[key].attendanceHours+=Number(log.totalHoursWorked||0)});timesheets.filter(entry=>entry.entryType==="Standard"&&entry.status!=="Rejected").forEach(entry=>{const key=`${entry.staffId}|${attendanceWeekStart(entry.dateLogged)}`;if(groups[key])groups[key].timesheetHours+=Number(entry.hoursSpent||0)});return Object.values(groups).map(group=>({...group,gap:group.attendanceHours-group.timesheetHours})).filter(group=>group.gap>.25)}
function runAttendanceControls(){const today=operationDate();attendanceLogs.forEach(log=>{if(log.clockInTime&&!log.clockOutTime&&log.date<today&&log.status!=="On Leave"&&log.status!=="Missed Punch"){log.status="Missed Punch";log.requiresManagerReview=true;addAttendanceException(log,"Missed Punch",0,"Clock-out was not captured by 23:59.");writeAlert("MISSED_PUNCH",log.id,"Audit Supervisor",`Staff ID ${log.staffId} needs an approved estimated clock-out for ${log.date}.`)}});attendanceGaps().forEach(gap=>writeAlert("TIMESHEET_GAP",`${gap.staffId}-${gap.weekStart}`,"Manager",`Staff ID ${gap.staffId} has a ${gap.gap.toFixed(2)}-hour attendance-to-timesheet gap for the week of ${gap.weekStart}.`));const weeklyHours={};attendanceLogs.filter(log=>log.clockOutTime&&attendanceBusySeason(log.date)).forEach(log=>{const key=`${log.staffId}|${attendanceWeekStart(log.date)}`;weeklyHours[key]=(weeklyHours[key]||0)+Number(log.totalHoursWorked||0)});Object.entries(weeklyHours).forEach(([key,hours])=>{const [staffId,weekStart]=key,position=attendanceLogs.find(log=>log.staffId===staffId)?.position;if(position==="Audit Assistant"&&hours>60)writeAlert("BURNOUT_RISK",key,"Engagement Partner",`Audit Assistant staff ID ${staffId} recorded ${hours.toFixed(2)} attendance hours in the busy-season week of ${weekStart}.`)});saveOperations();renderAttendance()}
function renderAttendance(){syncAllApprovedLeaveAttendance();const active=attendanceLogs.filter(log=>log.date===operationDate()&&!log.clockOutTime&&["Present","Late"].includes(log.status)),month=operationDate().slice(0,7),monthLogs=attendanceLogs.filter(log=>log.date.startsWith(month)&&["Present","Late"].includes(log.status)),onTime=monthLogs.filter(log=>log.status==="Present").length,punctuality=monthLogs.length?`${(onTime/monthLogs.length*100).toFixed(0)}%`:"—",exceptions=attendanceExceptions.filter(item=>["Lateness","Missed Punch"].includes(item.exceptionType)),gaps=attendanceGaps();document.getElementById("attendanceClockedIn").textContent=active.length;document.getElementById("attendancePunctuality").textContent=punctuality;document.getElementById("attendanceExceptionsCount").textContent=exceptions.length;document.getElementById("attendanceGapCount").textContent=gaps.length;setSelectItems("visitEngagement",activeEngagements(),"Select engagement…");const exceptionTarget=document.getElementById("attendanceExceptionsTable");exceptionTarget.innerHTML=attendanceExceptions.length?attendanceExceptions.slice().reverse().map(item=>`<tr><td>${escapeHtml(item.staffId)}<br><span class="hint">${escapeHtml(item.date)}</span></td><td>${escapeHtml(item.exceptionType)}</td><td>${Number(item.minutesVariance||0)} min</td><td>${escapeHtml(item.reason||"—")}</td><td class="${item.status==="Pending"?"status-watch":""}">${escapeHtml(item.status)}</td><td>${item.status==="Pending"?`${item.exceptionType==="Missed Punch"?`<button data-attendance-exception="clockout" data-id="${item.id}">Set clock-out</button> `:""}<button data-attendance-exception="approve" data-id="${item.id}">Approve</button> <button data-attendance-exception="reject" data-id="${item.id}">Reject</button>`:"—"}</td></tr>`).join(""):'<tr><td colspan="6" class="hint">No attendance exceptions recorded.</td></tr>';const gapTarget=document.getElementById("timesheetGapTable");gapTarget.innerHTML=gaps.length?gaps.map(gap=>`<tr><td>${escapeHtml(gap.staffId)}</td><td>${escapeHtml(gap.weekStart)}</td><td>${gap.attendanceHours.toFixed(2)}</td><td>${gap.timesheetHours.toFixed(2)}</td><td class="status-risk">${gap.gap.toFixed(2)} hrs</td></tr>`).join(""):'<tr><td colspan="5" class="hint">No attendance-to-timesheet gaps above 15 minutes.</td></tr>';const attendanceTarget=document.getElementById("attendanceTable");attendanceTarget.innerHTML=attendanceLogs.length?attendanceLogs.slice().sort((a,b)=>`${b.date}${b.clockInTime||""}`.localeCompare(`${a.date}${a.clockInTime||""}`)).map(log=>`<tr><td>${escapeHtml(log.staffId)}<br><span class="hint">${escapeHtml(log.position||"Not set")}</span></td><td>${escapeHtml(log.date)}</td><td>${escapeHtml(log.workLocation.replaceAll("_"," "))}</td><td>${escapeHtml(log.clockInTime?.replace("T"," ")||"—")}<br>${escapeHtml(log.clockOutTime?.replace("T"," ")||"—")}</td><td>${Number(log.totalHoursWorked||0).toFixed(2)}</td><td class="${["Late","Missed Punch"].includes(log.status)?"status-risk":log.status==="On Leave"?"status-watch":"status-ok"}">${escapeHtml(log.status)}${log.requiresManagerReview?" · Review":""}</td><td>${escapeHtml(log.approvedBy||"—")}</td></tr>`).join(""):'<tr><td colspan="7" class="hint">No attendance records logged.</td></tr>';const visitsTarget=document.getElementById("siteVisitsTable");visitsTarget.innerHTML=clientSiteVisits.length?clientSiteVisits.slice().reverse().map(visit=>`<tr><td>${escapeHtml(visit.staffId)}</td><td>${escapeHtml(visit.clientReference)}<br><span class="hint">${escapeHtml(engagementById(visit.engagementId)?.companyName||"Archived engagement")}</span></td><td>${escapeHtml(visit.checkInTime.replace("T"," "))}<br>${escapeHtml(visit.checkOutTime?.replace("T"," ")||"—")}</td><td>${escapeHtml(visit.gpsCoordinates||"Not recorded")}</td><td>${escapeHtml(visit.supervisorSignoff||"Pending")}</td></tr>`).join(""):'<tr><td colspan="5" class="hint">No client site visits logged.</td></tr>'}
function initialiseAttendance(){document.getElementById("attendanceDate").value=operationDate();document.getElementById("attendanceForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),staffId=data.get("attendanceStaffId").trim(),date=data.get("attendanceDate"),clockIn=data.get("attendanceClockIn"),clockOut=data.get("attendanceClockOut"),leave=approvedLeaveFor(staffId,date);if(leave){showAttendanceNotice("Clocking is blocked because this date is covered by an approved leave request.",true);return}if(clockOut&&new Date(clockOut)<new Date(clockIn)){showAttendanceNotice("Clock-out cannot be earlier than clock-in.",true);return}const lateMinutes=minutesAfter(timeOfDay(clockIn),"08:15"),hours=attendanceHours(clockIn,clockOut),earlyMinutes=clockOut?Math.max(0,-minutesAfter(timeOfDay(clockOut),"17:00")):0,overtimeMinutes=clockOut&&attendanceBusySeason(date)?Math.max(0,minutesAfter(timeOfDay(clockOut),"18:00")):0,reason=data.get("attendanceReason").trim();if(lateMinutes>0&&!reason){showAttendanceNotice("A reason is required for a clock-in after 08:15.",true);return}let status=lateMinutes>0?"Late":hours&&hours<4?"Half Day":"Present";const existing=attendanceLogs.find(log=>log.staffId===staffId&&log.date===date),record={id:existing?.id||crypto.randomUUID(),staffId,position:data.get("attendancePosition"),date,clockInTime:existing?.clockInTime||clockIn,clockOutTime:clockOut||existing?.clockOutTime||null,workLocation:data.get("attendanceLocation"),ipAddress:data.get("attendanceIpAddress").trim(),status,totalHoursWorked:hours||attendanceHours(existing?.clockInTime,existing?.clockOutTime),approvedBy:existing?.approvedBy||null,requiresManagerReview:data.get("attendanceLocation")==="REMOTE"&&!approvedAttendanceNetwork(data.get("attendanceIpAddress").trim()),createdAt:existing?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(existing)attendanceLogs[attendanceLogs.findIndex(log=>log.id===existing.id)]=record;else attendanceLogs.push(record);if(lateMinutes>0)addAttendanceException(record,"Lateness",lateMinutes,reason);if(earlyMinutes>0)addAttendanceException(record,"Early Departure",earlyMinutes,reason);if(overtimeMinutes>0)addAttendanceException(record,"Overtime",overtimeMinutes,reason||"Busy-season overtime recorded.");if(record.requiresManagerReview)writeAlert("REMOTE_NETWORK_REVIEW",record.id,"Manager",`Remote attendance by staff ID ${staffId} was recorded from an unrecognized network and needs review.`);saveOperations();form.reset();document.getElementById("attendanceDate").value=operationDate();renderAttendance();showAttendanceNotice(`${staffId} attendance recorded as ${status}.`) });document.getElementById("siteVisitForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),engagement=engagementById(data.get("visitEngagement")),checkIn=data.get("visitCheckIn"),checkOut=data.get("visitCheckOut");if(!engagement||!checkIn){showAttendanceNotice("Select an active engagement and capture a site check-in.",true);return}if(checkOut&&new Date(checkOut)<new Date(checkIn)){showAttendanceNotice("Visit check-out cannot be earlier than check-in.",true);return}clientSiteVisits.push({id:crypto.randomUUID(),staffId:data.get("visitStaffId").trim(),clientReference:data.get("visitClient").trim(),engagementId:engagement.id,checkInTime:checkIn,checkOutTime:checkOut||null,gpsCoordinates:data.get("visitGps").trim(),supervisorSignoff:data.get("visitSupervisor").trim()||null,createdAt:new Date().toISOString()});saveOperations();form.reset();renderAttendance();showAttendanceNotice("Client site visit logged for Supervisor verification.")});document.getElementById("attendanceExceptionsTable").addEventListener("click",event=>{const button=event.target.closest("button[data-attendance-exception]");if(!button)return;const exception=attendanceExceptions.find(item=>item.id===button.dataset.id);if(!exception)return;const attendance=attendanceLogs.find(log=>log.id===exception.attendanceId);if(button.dataset.attendanceException==="clockout"){const clockOut=prompt("Enter the estimated clock-out timestamp (YYYY-MM-DDTHH:MM).");if(!clockOut||Number.isNaN(new Date(clockOut).getTime()))return;if(attendance&&new Date(clockOut)>=new Date(attendance.clockInTime)){attendance.clockOutTime=clockOut;attendance.totalHoursWorked=attendanceHours(attendance.clockInTime,clockOut);attendance.status=attendance.status==="Missed Punch"?"Present":attendance.status;attendance.requiresManagerReview=true;exception.reason=exception.reason?`${exception.reason} Estimated clock-out: ${clockOut}.`:`Estimated clock-out: ${clockOut}.`}else{showAttendanceNotice("Estimated clock-out must be after the recorded clock-in.",true);return}}const approver=prompt("Enter the approving Manager or Audit Supervisor staff ID.");if(!approver)return;exception.status=button.dataset.attendanceException==="reject"?"Rejected":"Approved";exception.approvedBy=approver;exception.approvedAt=new Date().toISOString();if(attendance)attendance.approvedBy=approver;saveOperations();renderAttendance();showAttendanceNotice(`Attendance exception ${exception.status.toLowerCase()}.`)});document.getElementById("runAttendanceControls").addEventListener("click",()=>{runAttendanceControls();showAttendanceNotice("Attendance, missed-punch, burnout and timesheet-gap controls have been scanned.")});syncAllApprovedLeaveAttendance();renderAttendance()}

function showHelpdeskNotice(message,error=false){const notice=document.getElementById("helpdeskNotice");notice.textContent=message;notice.classList.add("show");notice.style.background=error?"#fbe8e8":"";notice.style.borderColor=error?"#d8aaaa":"";notice.style.color=error?"#8b2828":"";clearTimeout(showHelpdeskNotice.timer);showHelpdeskNotice.timer=setTimeout(()=>notice.classList.remove("show"),8000)}
function slaHours(priority){return{Critical:1,High:4,Medium:24,Low:48}[priority]||24}
function supportRouting(category){return{IT:"System Administrator","Audit Software":"Audit Supervisor",Tax:"Tax Manager",Billing:"Practice Administration","Client Documents":"Audit Supervisor",Attendance:"System Administrator"}[category]||"Practice Administration"}
function ticketById(id){return tickets.find(ticket=>ticket.id===id)}
function ticketNumber(){return `ALC-${new Date().getFullYear()}-${String(tickets.length+1).padStart(4,"0")}`}
function refreshHelpdeskSelects(){setSelectItems("ticketEngagement",activeEngagements(),"No engagement link");const target=document.getElementById("commentTicket"),previous=target.value;target.innerHTML=`<option value="">Select ticket…</option>${tickets.slice().reverse().map(ticket=>`<option value="${ticket.id}">${escapeHtml(ticket.ticketNumber)} — ${escapeHtml(ticket.subject)}</option>`).join("")}`;if([...target.options].some(option=>option.value===previous))target.value=previous}
function renderHelpdesk(){
  refreshHelpdeskSelects();const open=tickets.filter(ticket=>["Open","In Progress","Pending Client"].includes(ticket.status)),resolved=tickets.filter(ticket=>ticket.status==="Resolved"),breaches=tickets.filter(ticket=>ticket.slaBreached),categories={};tickets.forEach(ticket=>categories[ticket.category]=(categories[ticket.category]||0)+1);const topCategory=Object.entries(categories).sort((a,b)=>b[1]-a[1])[0]?.[0]||"—";document.getElementById("ticketOpenCount").textContent=open.length;document.getElementById("ticketSlaRisk").textContent=breaches.length;document.getElementById("ticketResolvedCount").textContent=resolved.length;document.getElementById("ticketTopCategory").textContent=topCategory;
  const knowledgeTarget=document.getElementById("knowledgeTable");knowledgeTarget.innerHTML=knowledgeBase.length?knowledgeBase.slice().reverse().map(article=>`<tr><td>${escapeHtml(article.title)}</td><td>${escapeHtml(article.category)}</td><td>${article.clientVisible?"Client and staff":"Internal staff"}</td><td>${article.views}</td></tr>`).join(""):'<tr><td colspan="4" class="hint">No knowledge-base articles published.</td></tr>';
  const statuses=["Open","In Progress","Pending Client","Resolved","Closed"],board=document.getElementById("ticketKanban");board.innerHTML=statuses.map(status=>{const items=tickets.filter(ticket=>ticket.status===status),cards=items.map(ticket=>{const due=new Date(ticket.slaDueAt),minutes=Math.max(0,Math.round((due-Date.now())/60000)),ticketCommentsCount=ticketComments.filter(comment=>comment.ticketId===ticket.id).length;return `<article class="lifecycle-card"><h4>${escapeHtml(ticket.ticketNumber)} · ${escapeHtml(ticket.subject)}</h4><p>${escapeHtml(ticket.category)} · ${escapeHtml(ticket.assignedPosition)}</p><div><span class="pill ${ticket.priority==="Critical"||ticket.slaBreached?"critical":ticket.priority==="High"?"warning":""}">${escapeHtml(ticket.priority)}</span><span class="pill">${ticketCommentsCount} updates</span></div><p class="inline-metric ${ticket.slaBreached?"status-risk":""}">${ticket.slaBreached?"SLA breached":`${minutes} min to SLA`}</p><div class="client-actions">${ticket.category==="Client Documents"&&["Open","In Progress","Pending Client"].includes(ticket.status)?`<button data-ticket-action="pbc" data-id="${ticket.id}">Send PBC reminder</button>`:""}${ticket.status==="Resolved"?`<button data-ticket-action="close" data-id="${ticket.id}">Close</button>`:""}</div></article>`}).join("")||'<p class="stage-note">No tickets</p>';return `<section class="kanban-column"><h3>${escapeHtml(status)} <span class="kanban-count">${items.length}</span></h3>${cards}</section>`}).join("")
}
function runSlaControls(){const now=Date.now();tickets.forEach(ticket=>{if(ticket.status==="Resolved"){if(ticket.resolvedAt&&now-new Date(ticket.resolvedAt).getTime()>48*3600000){ticket.status="Closed";ticket.closedAt=new Date().toISOString()}return}if(ticket.status==="Closed")return;if(new Date(ticket.slaDueAt).getTime()<now){ticket.slaBreached=true;ticket.priority="Critical";writeAlert("TICKET_SLA_BREACH",ticket.id,"Manager",`Ticket ${ticket.ticketNumber} breached its SLA and was escalated to Critical.`)}});saveOperations();renderHelpdesk();renderDashboard()}
function initialiseHelpdesk(){
  document.getElementById("ticketForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),priority=data.get("ticketPriority"),createdAt=new Date(),ticket={id:crypto.randomUUID(),ticketNumber:ticketNumber(),subject:data.get("ticketSubject").trim(),description:data.get("ticketDescription").trim(),requesterType:data.get("ticketRequesterType"),requesterReference:data.get("ticketRequester").trim(),engagementId:data.get("ticketEngagement")||null,priority,status:"Open",category:data.get("ticketCategory"),assignedPosition:supportRouting(data.get("ticketCategory")),attachmentReference:data.get("ticketAttachment").trim(),createdAt:createdAt.toISOString(),updatedAt:createdAt.toISOString(),slaDueAt:new Date(createdAt.getTime()+slaHours(priority)*3600000).toISOString(),slaBreached:false};tickets.push(ticket);writeAlert("TICKET_CREATED",ticket.id,ticket.assignedPosition,`New ${priority} ${ticket.category} support ticket ${ticket.ticketNumber}.`);saveOperations();form.reset();renderHelpdesk();renderDashboard();showHelpdeskNotice(`${ticket.ticketNumber} routed to ${ticket.assignedPosition} with a ${slaHours(priority)}-hour SLA.`)});
  document.getElementById("knowledgeForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form);knowledgeBase.push({id:crypto.randomUUID(),title:data.get("articleTitle").trim(),category:data.get("articleCategory"),content:data.get("articleContent").trim(),clientVisible:data.get("articleClientVisible")==="on",views:0,createdAt:new Date().toISOString()});saveOperations();form.reset();renderHelpdesk();showHelpdeskNotice("Knowledge-base article published.")});
  document.getElementById("ticketCommentForm").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),ticket=ticketById(data.get("commentTicket"));if(!ticket){showHelpdeskNotice("Select a support ticket before adding an update.",true);return}ticketComments.push({id:crypto.randomUUID(),ticketId:ticket.id,authorReference:data.get("commentAuthor").trim(),message:data.get("commentMessage").trim(),isInternalNote:data.get("commentInternal")==="on",attachmentReference:data.get("commentAttachment").trim(),createdAt:new Date().toISOString()});ticket.status=data.get("commentStatus");ticket.updatedAt=new Date().toISOString();if(ticket.status==="Resolved")ticket.resolvedAt=ticket.updatedAt;saveOperations();form.reset();renderHelpdesk();renderDashboard();showHelpdeskNotice(`Update recorded against ${ticket.ticketNumber}.`)});
  document.getElementById("ticketKanban").addEventListener("click",event=>{const button=event.target.closest("button[data-ticket-action]");if(!button)return;const ticket=ticketById(button.dataset.id);if(!ticket)return;if(button.dataset.ticketAction==="pbc"){writeAlert("PBC_REMINDER",ticket.id,"Audit Supervisor",`PBC reminder requested from ticket ${ticket.ticketNumber}. Production sends the client reminder through the external portal.`);ticket.status="Pending Client";ticket.updatedAt=new Date().toISOString();showHelpdeskNotice("PBC reminder queued and ticket moved to Pending Client.")}if(button.dataset.ticketAction==="close"){ticket.status="Closed";ticket.closedAt=new Date().toISOString();showHelpdeskNotice("Resolved ticket closed.")}saveOperations();renderHelpdesk();renderDashboard()});
  document.getElementById("runSlaControls").addEventListener("click",()=>{runSlaControls();showHelpdeskNotice("SLA control scan completed. Breached tickets were escalated.")});renderHelpdesk()
}

renderStaticFields();renderAccessControl();initialiseTabs();initialiseForm();listenForClientActions();initialiseLifecycle();initialiseCommunicationHub();initialiseOperations();initialiseAudit();initialiseHR();initialiseAttendance();initialiseVault();initialiseHelpdesk();initialiseDashboard();showRecommendation();showTaxComplianceProfile();renderClientList();
